SourceCode.Declaration:
/// <summary>
/// The price simulator's answer for one line: unit price, gross, discount and net amount, in the store's currency.
/// </summary>
[DataContractAttribute]
class HSMobileOpsPriceCheckResponse
{
    boolean          success;
    str              errorCode;
    str              message;
    str              itemId;
    str              itemName;
    real             quantity;
    str              unitId;
    real             unitPrice;
    real             grossAmount;
    real             discountAmount;
    real             discountPct;
    real             netAmount;
    str              offerName;
    str              currency;
    boolean          priceIncludesTax;
    str              storeName;
}

Method.Source:
